"""Problem definitions for the high-dimensional linear-composite class.

Each :class:`Problem` bundles the four pure functions the simulators need:

* ``grad(params, data, target)``      -> per-sample gradient, shape ``(D, M)``
* ``target(optimal_params, data)``    -> label(s) generated by the teacher
* ``f(q)``                            -> population "gradient profile" used by the
  B-functionals (``discounts.py``); ``q`` carries the logits in its last axis,
  laid out as ``[student (M) | teacher (M*)]``
* ``risk_from_B(B)``                  -> scalar risk from the low-dim statistic ``B``

These are the same maps that lived in the old ``risks_and_discounts.py``; they are
collected here behind a small registry so ``simulate``/``dynamics`` can close over a
single static object.
"""
from __future__ import annotations

from typing import Callable, NamedTuple

import jax
import jax.numpy as jnp
from jax import jit
from jax.nn import log_softmax, sigmoid, softmax
from numpy.polynomial.hermite import hermgauss


class Problem(NamedTuple):
    name: str
    grad: Callable        # (params, data, target) -> (D, M)
    target: Callable      # (optimal_params, data) -> target
    f: Callable           # (q) -> profile, q[..., :M]=student, q[..., M:]=teacher
    risk_from_B: Callable  # (B) -> scalar


# --------------------------------------------------------------------------- #
# Linear regression
# --------------------------------------------------------------------------- #
@jit
def _grad_linreg(params, data, target):
    return jnp.outer(data, data @ params - target)


@jit
def _target_linreg(optimal_params, data):
    return optimal_params.T @ data


@jit
def _f_linreg(q):
    m = q.shape[-1] // 2
    return q[..., :m] - q[..., m:]


@jit
def _risk_from_B_linreg(B):
    n = B.shape[0] // 2
    return (jnp.trace(B) - 2 * jnp.trace(B[:n, n:])) / 2


# --------------------------------------------------------------------------- #
# Logistic regression (binary)
# --------------------------------------------------------------------------- #
@jit
def _logreg_prob(data, params):
    return sigmoid(params.T @ data)


@jit
def _grad_logreg(params, data, target):
    return jnp.outer(data, _logreg_prob(data, params) - target)


@jit
def _target_logreg(optimal_params, data):
    return sigmoid(optimal_params.T @ data)


@jit
def _f_logreg(q):
    m = q.shape[-1] // 2
    return sigmoid(q[..., :m]) - sigmoid(q[..., m:])


@jit
def _risk_from_B_logreg(B):
    # Binary logistic regression only: B is 2x2.
    B00, B11, B01 = B[0, 0], B[1, 1], B[0, 1]
    num_points = 20
    points, weights = hermgauss(num_points)
    points = jnp.asarray(points) * jnp.sqrt(2.0)
    weights = jnp.asarray(weights)
    t1 = -B01 * jnp.exp(jnp.sqrt(B11) * points) / (1 + jnp.exp(jnp.sqrt(B11) * points)) ** 2
    t2 = jnp.log1p(jnp.exp(jnp.sqrt(B00) * points))
    return jnp.sum(weights * (t1 + t2)) / jnp.sqrt(jnp.pi)


# --------------------------------------------------------------------------- #
# Real phase retrieval
# --------------------------------------------------------------------------- #
@jit
def _grad_real_phase_ret(params, data, target):
    pd = params.T @ data
    return jnp.outer(data, 4 * pd * (pd ** 2 - target))


@jit
def _target_real_phase_ret(optimal_params, data):
    return (optimal_params.T @ data) ** 2


@jit
def _f_real_phase_ret(q):
    m = q.shape[-1] // 2
    q1, q2 = q[..., :m], q[..., m:]
    return 4 * q1 * (q1 ** 2 - q2 ** 2)


@jit
def _risk_from_B_real_phase_ret(B):
    m = B.shape[0] // 2
    B11, B12, B22 = B[:m, :m], B[:m, m:], B[m:, m:]
    return (3 * jnp.trace(B11 @ B11) - 2 * jnp.trace(B11 @ B22)
            - 4 * jnp.trace(B12 @ B12.T) + 3 * jnp.trace(B22 @ B22))


PROBLEMS = {
    "linreg": Problem("linreg", _grad_linreg, _target_linreg, _f_linreg, _risk_from_B_linreg),
    "logreg": Problem("logreg", _grad_logreg, _target_logreg, _f_logreg, _risk_from_B_logreg),
    "real_phase_ret": Problem(
        "real_phase_ret", _grad_real_phase_ret, _target_real_phase_ret,
        _f_real_phase_ret, _risk_from_B_real_phase_ret,
    ),
}


def make_softmax_problem(classes: int, *, risk_samples: int = 8_192,
                         risk_seed: int = 0) -> Problem:
    """Create a ``classes``-class soft-label teacher--student problem.

    The student and teacher use ``classes - 1`` free logits, with the last
    class fixed as the reference logit.  This removes softmax's additive gauge
    direction and keeps the Gaussian order parameter nonsingular.
    The population cross-entropy is evaluated from ``B`` with fixed Gaussian
    Monte Carlo draws, so repeated calls along an ODE path are deterministic.
    """
    if classes < 2:
        raise ValueError("classes must be at least two")
    rank = classes - 1
    base = jax.random.normal(
        jax.random.PRNGKey(risk_seed), (risk_samples, 2 * rank)
    )

    def probabilities(free_logits):
        reference = jnp.zeros(free_logits.shape[:-1] + (1,))
        return softmax(jnp.concatenate([free_logits, reference], axis=-1), axis=-1)

    @jit
    def grad(params, data, target):
        return jnp.outer(data, probabilities(params.T @ data)[:-1] - target[:-1])

    @jit
    def target(optimal_params, data):
        return probabilities(optimal_params.T @ data)

    @jit
    def f(q):
        return probabilities(q[..., :rank])[..., :-1] - probabilities(
            q[..., rank:]
        )[..., :-1]

    @jit
    def risk_from_B(B):
        symmetric = (B + B.T) / 2
        scale = jnp.maximum(jnp.trace(symmetric) / (2 * rank), 1.0)
        chol = jnp.linalg.cholesky(
            symmetric + 1e-10 * scale * jnp.eye(2 * rank)
        )
        q = base @ chol.T
        student_log_probability = log_softmax(
            jnp.concatenate([q[:, :rank], jnp.zeros((risk_samples, 1))], axis=1),
            axis=-1,
        )
        teacher_probability = probabilities(q[:, rank:])
        return -jnp.mean(
            jnp.sum(teacher_probability * student_log_probability, axis=-1)
        )

    return Problem(
        f"softmax_{classes}", grad, target, f, risk_from_B
    )


def get_problem(name: str) -> Problem:
    try:
        return PROBLEMS[name]
    except KeyError:
        raise NotImplementedError(f"Problem {name!r} not implemented") from None


# --------------------------------------------------------------------------- #
# Label-dependent losses on Gaussian-mixture data (gmm_adam.tex)
# --------------------------------------------------------------------------- #
class MixtureProblem(NamedTuple):
    """A linear composite loss whose gradient profile may depend on the label.

    Data are ``c ~ priors`` and ``x | c ~ N(xbar_c, K)``. ``f(q, c, w)`` is the
    single-sample gradient profile (shape ``(M,)``) at predictions
    ``q = (Theta^+)^T x`` (``M+`` entries), class ``c`` and a standard Gaussian
    label-noise draw ``w`` (``M`` entries). ``risk(B, O)`` / ``error(B, O)`` are
    population quantities as functions of ``B`` and the mean overlaps
    ``O = (Theta^+)^T Xbar`` (gmm_adam.tex eq. gmm_risk). Centered
    teacher--student problems are the one-class, zero-mean case.
    """
    name: str
    outputs: int          # M
    priors: jnp.ndarray   # (C,)
    f: Callable           # (q, c, w) -> (M,)
    risk: Callable        # (B, O) -> scalar
    error: Callable       # (B, O) -> scalar, or None


def _gaussian_draws(dim, samples, seed):
    return jax.random.normal(jax.random.PRNGKey(seed), (samples, dim))


def make_mixture_linreg(outputs: int = 1, noise_std: float = 0.0) -> MixtureProblem:
    """Teacher--student least squares on centered data, ``f = q_1 - q_2 - sigma w``.

    The risk includes the label-noise floor ``M sigma^2 / 2``.
    """
    m = outputs

    def f(q, c, w):
        return q[:m] - q[m:] - noise_std * w

    def risk(B, O):
        return (jnp.trace(B[:m, :m]) - 2 * jnp.trace(B[:m, m:])
                + jnp.trace(B[m:, m:]) + m * noise_std ** 2) / 2

    return MixtureProblem(f"linreg_m{m}", m, jnp.ones(1), f, risk, None)


def make_mixture_softmax_teacher(classes: int, *, risk_samples: int = 2 ** 15,
                                 risk_seed: int = 0) -> MixtureProblem:
    """Soft-label softmax teacher--student with ``classes - 1`` free logits.

    Same model as :func:`make_softmax_problem`, written as a mixture problem
    (one centered class).
    """
    rank = classes - 1
    g = _gaussian_draws(2 * rank, risk_samples, risk_seed)

    def probabilities(free_logits):
        reference = jnp.zeros(free_logits.shape[:-1] + (1,))
        return softmax(jnp.concatenate([free_logits, reference], axis=-1), axis=-1)

    def f(q, c, w):
        return probabilities(q[:rank])[:-1] - probabilities(q[rank:])[:-1]

    def risk(B, O):
        from utils import sym_sqrt
        q = g @ sym_sqrt(B)
        student = jnp.concatenate([q[:, :rank], jnp.zeros((risk_samples, 1))], axis=1)
        return -jnp.mean(jnp.sum(probabilities(q[:, rank:]) * log_softmax(student, axis=-1),
                                 axis=-1))

    return MixtureProblem(f"softmax_teacher_{classes}", rank, jnp.ones(1), f, risk, None)


def make_gmm_logistic(priors=(0.5, 0.5)) -> MixtureProblem:
    """Binary logistic regression on a two-component mixture (labels 0/1).

    ``f(q; c) = sigmoid(q) - c``; risk and error by Gauss--Hermite quadrature.
    """
    priors = jnp.asarray(priors)
    nodes, weights = hermgauss(64)
    nodes = jnp.asarray(nodes) * jnp.sqrt(2.0)
    weights = jnp.asarray(weights) / jnp.sqrt(jnp.pi)
    signs = jnp.array([-1.0, 1.0])

    def f(q, c, w):
        return sigmoid(q[:1]) - c

    def risk(B, O):
        q = O[0][:, None] + jnp.sqrt(jnp.maximum(B[0, 0], 0.0)) * nodes[None, :]
        return jnp.sum(priors * (jnp.log1p(jnp.exp(-signs[:, None] * q)) @ weights))

    def error(B, O):
        scale = jnp.sqrt(jnp.maximum(B[0, 0], 1e-300))
        return jnp.sum(priors * jax.scipy.stats.norm.cdf(-signs * O[0] / scale))

    return MixtureProblem("gmm_logistic", 1, priors, f, risk, error)


def make_gmm_softmax(priors, *, risk_samples: int = 2 ** 15,
                     risk_seed: int = 0) -> MixtureProblem:
    """``C``-class softmax regression on a ``C``-component mixture, ``M = C`` logits.

    ``f(q; c) = softmax(q) - e_c``. Risk and error use fixed Gaussian draws, so
    they are deterministic functions of ``(B, O)`` shared by Adam and the ODE.
    """
    priors = jnp.asarray(priors)
    classes = len(priors)
    g = _gaussian_draws(classes, risk_samples, risk_seed)

    def f(q, c, w):
        return softmax(q) - jax.nn.one_hot(c, classes, dtype=q.dtype)

    def logits(B, O):
        from utils import sym_sqrt
        return O.T[:, None, :] + (g @ sym_sqrt(B))[None]          # (C, n, C)

    def risk(B, O):
        q = logits(B, O)
        own = jnp.take_along_axis(q, jnp.arange(classes)[:, None, None], axis=2)[..., 0]
        return jnp.sum(priors * jnp.mean(jax.nn.logsumexp(q, axis=2) - own, axis=1))

    def error(B, O):
        wrong = jnp.argmax(logits(B, O), axis=2) != jnp.arange(classes)[:, None]
        return jnp.sum(priors * jnp.mean(wrong.astype(priors.dtype), axis=1))

    return MixtureProblem(f"gmm_softmax_{classes}", classes, priors, f, risk, error)


def softmax_class_metrics(B, O, *, samples: int = 2 ** 15, seed: int = 0,
                          batch_size: int = 8):
    """Per-class cross-entropy ``ell_c = E[-log p_c(x) | c]`` and error
    ``err_c = P(argmax q != c | c)`` for softmax with ``M = C`` logits, from
    ``q | c ~ N(O[:, c], B)`` and fixed Gaussian draws (deterministic in ``(B, O)``).

    The shared noise ``g @ sym_sqrt(B)`` is formed once and classes are processed
    in ``lax.map`` batches, so memory is ``O(samples * C)`` rather than
    ``O(samples * C^2)``.
    """
    from utils import sym_sqrt
    classes = B.shape[0]
    noise = _gaussian_draws(classes, samples, seed) @ sym_sqrt(B)

    def one(c):
        q = O[:, c][None, :] + noise
        loss = jnp.mean(jax.nn.logsumexp(q, axis=1) - q[:, c])
        error = jnp.mean((jnp.argmax(q, axis=1) != c).astype(q.dtype))
        return loss, error

    return jax.lax.map(one, jnp.arange(classes), batch_size=batch_size)
